INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 24, 'theory', 'Quiz: send, throw and yield from');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 0, 'What happens on g.send(5) right after g = gen()?', '["The value 5 is remembered", "TypeError: cannot send a non-None value to a just-started generator", "The generator returns 5", "Nothing: send is ignored"]', 1, 'Before the first yield there is nothing to receive a value: you need next first (or send(None)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 1, 'What does the send method return?', '["Always None", "The value that was just sent", "The value yielded by the next yield", "The state of the generator"]', 2, 'send resumes the generator and returns whatever it yields at the next yield.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 2, 'What does g.close() do?', '["Removes the generator from memory immediately", "Throws GeneratorExit at the pause point, and finally blocks run", "Restarts the generator", "Raises StopIteration in the caller"]', 1, 'GeneratorExit unwinds the generator''s stack; if the generator then tries to yield a value, a RuntimeError is raised.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 3, 'Where is the value that a generator returned with return?', '["In the for loop variable", "In the result of next", "In the value attribute of the StopIteration exception", "In the gen.result attribute"]', 2, 'A for loop discards it, while yield from turns it into the value of its expression.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 4, 'What does result = yield from inner() mean?', '["The outer generator yields all values of inner and gets its return value in result", "inner runs in a separate thread", "inner is called once and returns a list", "result is the last yielded value"]', 0, 'yield from delegates the work to inner (send/throw/close pass straight through) and returns its result.');
